mapper.select:
SELECT id, owner_user_id, storage_provider, bucket, object_key, public_url, mime_type, byte_size,
       width, height, linked_resource_type, linked_resource_id, status, created_at, deleted_at, purge_after_at
FROM media.media_files
WHERE status = 'DELETED' AND purge_after_at <= #{now}
ORDER BY purge_after_at
LIMIT #{limit}

