WHERE id = #{mediaFileId} AND status = 'DELETED'

mapper.select:
SELECT COUNT(*) FROM (
  SELECT p.id FROM community.posts p
  WHERE p.deleted_at IS NULL AND p.moderation_status = 'VISIBLE' AND p.visibility = 'PUBLIC'
    AND (p.cover_media_file_id = #{mediaFileId}
      OR EXISTS (SELECT 1 FROM community.post_media pm WHERE pm.post_id = p.id AND pm.media_file_id = #{mediaFileId}))
  UNION ALL
  SELECT t.id FROM community.threads t
  JOIN community.thread_media tm ON tm.thread_id = t.id
  WHERE t.deleted_at IS NULL AND t.moderation_status = 'VISIBLE' AND tm.media_file_id = #{mediaFileId}
) published
